head.b:skin:
/* ── Reset & Base ─────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg:        #F7F6F2;
  --surface:   #FFFFFF;
  --border:    #E8E6DF;
  --text:      #1A1A1A;
  --text-sub:  #6B6B6B;
  --accent:    #4361EE;
  --accent-lt: #EEF1FD;
  --radius:    12px;
  --shadow:    0 2px 12px rgba(0,0,0,.07);
  --shadow-hv: 0 8px 28px rgba(0,0,0,.12);
}

html { scroll-behavior: smooth; }

body {
  background: var(--bg);
  color: var(--text);
  font-family: 'Noto Sans KR', 'Inter', sans-serif;
  font-size: 16px;
  line-height: 1.75;
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }
img { max-width: 100%; display: block; }

/* ── Header ─────────────────────────────────────────── */
#header-wrap {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(247,246,242,.92);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
}

#header-inner {
  max-width: 1100px;
  margin: 0 auto;
  padding: 0 24px;
  height: 64px;
  display: flex;
  align-items: center;
}

.header-content h1 {
  font-size: 1.25rem;
  font-weight: 700;
  letter-spacing: -.02em;
}

.header-content h1 a {
  background: linear-gradient(135deg, #4361EE, #9B59B6);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.header-content p.header-desc {
  font-size: .78rem;
  color: var(--text-sub);
  margin-top: 2px;
}

/* ── Hero ───────────────────────────────────────────── */
.hero {
  max-width: 1100px;
  margin: 48px auto 0;
  padding: 0 24px;
  text-align: center;
}

.hero-badge {
  display: inline-block;
  background: var(--accent-lt);
  color: var(--accent);
  font-size: .72rem;
  font-weight: 600;
  letter-spacing: .08em;
  text-transform: uppercase;
  padding: 4px 12px;
  border-radius: 100px;
  margin-bottom: 20px;
}

.hero h2 {
  font-size: 2.4rem;
  font-weight: 700;
  line-height: 1.25;
  letter-spacing: -.03em;
}

.hero p {
  margin-top: 14px;
  font-size: 1.05rem;
  color: var(--text-sub);
  max-width: 560px;
  margin-left: auto;
  margin-right: auto;
}

.hero-divider {
  width: 48px;
  height: 3px;
  background: linear-gradient(90deg, #4361EE, #9B59B6);
  border-radius: 4px;
  margin: 28px auto 0;
}

/* ── Layout ─────────────────────────────────────────── */
#outer-wrapper {
  max-width: 1100px;
  margin: 40px auto 80px;
  padding: 0 24px;
  display: grid;
  grid-template-columns: 1fr 300px;
  gap: 40px;
}

/* ── Post Cards ─────────────────────────────────────── */
.post-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 28px 32px;
  margin-bottom: 20px;
  box-shadow: var(--shadow);
  transition: transform .2s ease, box-shadow .2s ease;
}

.post-card:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-hv);
}

.post-meta {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: .78rem;
  color: var(--text-sub);
  margin-bottom: 12px;
  flex-wrap: wrap;
}

.post-label {
  background: var(--accent-lt);
  color: var(--accent);
  font-size: .7rem;
  font-weight: 600;
  padding: 2px 9px;
  border-radius: 100px;
}

.post-title {
  font-size: 1.22rem;
  font-weight: 700;
  line-height: 1.35;
  letter-spacing: -.02em;
  margin-bottom: 10px;
  transition: color .15s;
}

.post-title:hover { color: var(--accent); }

.post-snippet {
  font-size: .9rem;
  color: var(--text-sub);
  line-height: 1.65;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.post-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 20px;
  padding-top: 16px;
  border-top: 1px solid var(--border);
}

.read-more {
  font-size: .82rem;
  font-weight: 600;
  color: var(--accent);
}

/* ── Post Page ──────────────────────────────────────── */
.post-body-wrap {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 40px 48px;
  box-shadow: var(--shadow);
}

.post-title-single {
  font-size: 1.9rem;
  font-weight: 700;
  line-height: 1.3;
  letter-spacing: -.03em;
  margin-bottom: 16px;
}

.post-body {
  font-size: .97rem;
  line-height: 1.85;
  color: #2C2C2C;
}

.post-body h2 {
  font-size: 1.35rem;
  font-weight: 700;
  margin: 36px 0 14px;
  padding-left: 14px;
  border-left: 3px solid var(--accent);
  letter-spacing: -.02em;
}

.post-body h3 {
  font-size: 1.1rem;
  font-weight: 600;
  margin: 28px 0 10px;
}

.post-body p { margin-bottom: 18px; }

.post-body ul, .post-body ol {
  padding-left: 1.4em;
  margin-bottom: 18px;
}

.post-body li { margin-bottom: 8px; }

.post-body a {
  color: var(--accent);
  border-bottom: 1px solid var(--accent-lt);
}

/* ── Sidebar ────────────────────────────────────────── */
#sidebar-wrap {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.sidebar-widget {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 22px 24px;
  box-shadow: var(--shadow);
}

.widget-title {
  font-size: .8rem;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--text-sub);
  margin-bottom: 16px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--border);
}

.sidebar-widget ul { list-style: none; }

.sidebar-widget li {
  padding: 7px 0;
  font-size: .88rem;
  border-bottom: 1px solid var(--border);
}

.sidebar-widget li:last-child { border-bottom: none; }

.sidebar-widget li a {
  color: var(--text-sub);
  display: flex;
  align-items: center;
  gap: 6px;
  transition: color .15s;
}

.sidebar-widget li a:hover { color: var(--accent); }

/* ── Pagination ─────────────────────────────────────── */
.blog-pager {
  display: flex;
  justify-content: center;
  gap: 12px;
  margin-top: 12px;
}

.blog-pager a {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 9px 20px;
  border: 1px solid var(--border);
  border-radius: 8px;
  font-size: .85rem;
  font-weight: 500;
  background: var(--surface);
  color: var(--text);
  transition: all .15s;
}

.blog-pager a:hover {
  background: var(--accent);
  color: #fff;
  border-color: var(--accent);
}

/* ── Footer ─────────────────────────────────────────── */
#footer-wrap {
  background: var(--surface);
  border-top: 1px solid var(--border);
  padding: 36px 24px;
  text-align: center;
}

#footer-wrap p {
  font-size: .82rem;
  color: var(--text-sub);
}

#footer-wrap a { color: var(--accent); }

/* ── Responsive ─────────────────────────────────────── */
@media (max-width: 768px) {
  #outer-wrapper { grid-template-columns: 1fr; }
  #sidebar-wrap { display: none; }
  .post-body-wrap { padding: 24px 20px; }
  .post-card { padding: 22px 20px; }
  .hero h2 { font-size: 1.7rem; }
}
